import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SimpleEvent{EventType: packet.SimpleEventUnlockWorldTemplateSettings}
UNLOCK_WORLD_TEMPLATE_SETTINGS = bytes.fromhex("0300")

# generated by gophertunnel b8bd735:
# &packet.SimpleEvent{EventType: 300}
WIDE = bytes.fromhex("2c01")

GOLDENS = [
    pytest.param(
        v2225.SimpleEventPacket(subtype=v2225.SimpleEventPacket.Subtype.UNLOCK_WORLD_TEMPLATE_SETTINGS),
        UNLOCK_WORLD_TEMPLATE_SETTINGS,
        id="unlock-world-template-settings",
    ),
    pytest.param(v2225.SimpleEventPacket(subtype=300), WIDE, id="two-fixed-bytes-wide"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_simple_event_is_packet_64(version):
    assert version.PACKETS[64] is version.SimpleEventPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_simple_event_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_simple_event_decodes_from_its_golden(packet, golden):
    assert v2225.SimpleEventPacket.from_bytes(golden) == packet
